# Build the test grid, cross, and the listed objects; then stamp the UL pattern into the other panels.
grid = [[4]*27 for _ in range(27)]
for i in range(27): grid[13][i]=1; grid[i][13]=1
# Upper-left key pattern
for r,c,v in [(4,5,6),(4,6,6),(5,4,5),(5,5,2),(5,6,2),(6,3,3),(6,4,3),(6,5,2),(6,6,2),(7,5,1),(7,6,1),(8,5,1),(8,6,1)]: grid[r][c]=v
# Other panels' seed blocks
for r in range(4,8):
    for c in range(19,23): grid[r][c]=2
for r in range(20,22):
    for c in range(5,7): grid[r][c]=2
for r in range(19,21):
    for c in range(20,22): grid[r][c]=2
# Key pixels other than the 2 anchor; output scaling is target block side / key block side (2).
key=[(r,c,v) for r in range(3,10) for c in range(3,8) if (v:=grid[r][c]) not in (2,4)]
# anchor top-left for each seed, side scale, and flips (horizontal, vertical)
for ar,ac,s,fh,fv in [(4,19,2,True,False),(20,5,1,False,True),(19,20,1,True,True)]:
    for r,c,v in key:
        dy,dx=r-5,c-5
        by=(1-dy if fv else dy)
        bx=(1-dx if fh else dx)
        for yy in range(ar+by*s, ar+(by+1)*s):
            for xx in range(ac+bx*s, ac+(bx+1)*s):
                if not (0<=yy<27 and 0<=xx<27) or yy==13 or xx==13:
                    raise ValueError((yy,xx,v))
                grid[yy][xx]=v
print('non-background counts', {x:sum(cell==x for row in grid for cell in row) for x in range(10)})
for r,row in enumerate(grid):
    if any(x!=4 for x in row): print(r, ' '.join(map(str,row)))
